<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';use InaudisVote\Core\Authorization;use InaudisVote\Core\Database;$user=Authorization::requireRoles(['admin','organizer']);$pdo=Database::connection();if($user['role']==='admin'){$stmt=$pdo->query('SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 200');}else{$stmt=$pdo->prepare('SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id LEFT JOIN elections e ON a.entity_type="election" AND e.id=a.entity_id WHERE u.organization_id=:org OR e.organization_id=:org ORDER BY a.created_at DESC LIMIT 200');$stmt->execute(['org'=>(int)$user['organization_id']]);}$logs=$stmt->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auditoría | INAUDIS Vota</title><link rel="stylesheet" href="/assets/inaudis-vota.css"></head><body class="vota-ui"><div class="v-shell"><aside class="v-sidebar"><div class="v-brand"><span class="v-brandmark"></span><span>INAUDIS<small>VOTA</small></span></div><nav class="v-nav"><a href="/dashboard.php">⌂ &nbsp; Inicio</a><a href="/elections.php">✓ &nbsp; Votaciones</a><?php if($user['role']==='admin'):?><a href="/organizations.php">▦ &nbsp; Organizaciones</a><a href="/users.php">♙ &nbsp; Usuarios</a><?php endif;?><a class="active" href="/audit.php">◷ &nbsp; Auditoría</a></nav><div class="v-sidebar-foot"><?=htmlspecialchars($user['name'])?></div></aside><div class="v-main"><header class="v-topbar"><a class="v-link" href="/logout.php">Salir</a></header><main class="v-content"><div class="v-headrow"><div><div class="v-kicker">Trazabilidad</div><h1 class="v-title">Auditoría</h1><div class="v-accent-line"></div><p class="v-subtitle">Registro de los últimos 200 eventos relevantes de la plataforma.</p></div><span class="v-status v-status-open">✓ Registro activo</span></div><section class="v-card v-pad v-table-wrap"><table class="v-table"><thead><tr><th>Fecha</th><th>Evento</th><th>Entidad</th><th>Usuario</th><th>IP</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td style="white-space:nowrap"><?=htmlspecialchars($log['created_at'])?></td><td><strong style="color:var(--blue)"><?=htmlspecialchars($log['event_type'])?></strong></td><td><?=htmlspecialchars($log['entity_type'])?> #<?=htmlspecialchars((string)$log['entity_id'])?></td><td><?=htmlspecialchars((string)$log['user_name'])?></td><td class="v-muted"><?=htmlspecialchars((string)$log['ip_address'])?></td></tr><?php endforeach;?></tbody></table></section></main></div></div></body></html>